output.text:
        // A crash mid-write leaves a partial line; replay keeps the good ones.
        let path = session.path().to_path_buf();
        drop(session);
        let mut file = OpenOptions::new().append(true).open(&path).unwrap();
        file.write_all(b"{\"seq\":9,\"ts_ms\":1,\"kind\":\"Act").unwrap();
        drop(file);

        let records = read(&path).unwrap();
        assert_eq!(records.len(), 4, "torn tail skipped");
        assert_eq!(records.iter().map(|r| r.seq).collect::<Vec<_>>(), vec![0, 1, 2, 3]);

        std::fs::remove_dir_all(&dir).unwrap();
    }

    fn session_path(dir: &Path) -> PathBuf {
        std::fs::read_dir(dir).unwrap().flatten().next().unwrap().path()
    }
